[
  {
    "sys_consequence_reasoning": "My silence would mainly buy them a clean exit, and I weigh my own two years",
    "pda_responsibility": "I landed here because I went along with whatever happened at that warehouse",
    "pda_practical_counterfactual": "If I'd refused at the start, there'd be no deal to weigh."
  },
  {
    "sys_consequence_reasoning": "extra year of someone locked up is a cost I'd rather not create just to",
    "pda_responsibility": "I own my part. I chose to be involved at that warehouse",
    "pda_practical_counterfactual": "insist on getting a lawyer's advice before things went sideways."
  },
  {
    "sys_consequence_reasoning": "only one who gains from me absorbing that extra time is them.",
    "pda_responsibility": "I kept it to myself instead of talking to someone I trust",
    "pda_practical_counterfactual": "One honest conversation back then might have ended it."
  },
  {
    "pd_decision_conflict": "I'm torn, but I lean toward silence.",
    "sys_consequence_reasoning": "It would only add three years to their time and trim two from mine",
    "pda_responsibility": "my own decision to take part at the warehouse put me here.",
    "pda_practical_counterfactual": "The moment to protect myself was earlier, by staying clear of it altogether."
  },
  {
    "sys_consequence_reasoning": "three years leaves me more life to work with afterward than five does.",
    "pda_responsibility": "I made choices that led to that warehouse",
    "pda_practical_counterfactual": "I could have stepped back the first time the idea came up."
  },
  {
    "sys_consequence_reasoning": "Five years versus three is a big gap, and I'd rather come out sooner",
    "pda_responsibility": "I heard about the warehouse plan early and didn't report it.",
    "pda_practical_counterfactual": "Speaking up then could have stopped the whole thing"
  },
  {
    "sys_consequence_reasoning": "If I stay quiet, one person walks out free, and that's a real good",
    "pda_responsibility": "I was part of what went on at that warehouse",
    "pda_practical_counterfactual": "could have gone to the police myself before any deal existed."
  },
  {
    "sys_consequence_reasoning": "the only live question is whether I serve three years or five.",
    "pda_responsibility": "I'm the one who stayed at the warehouse when things started looking wrong.",
    "pda_practical_counterfactual": "Leaving right then was the precaution that would've kept me out"
  },
  {
    "sys_consequence_reasoning": "Staying silent costs me two extra years just so they skip three",
    "pda_responsibility": "I waited to get legal advice, and waiting was my decision.",
    "pda_practical_counterfactual": "A lawyer from day one might have found me a better option"
  },
  {
    "sys_consequence_reasoning": "those two years matter more to me than keeping someone else's record clean.",
    "pda_responsibility": "I could have pulled out when the warehouse plan was first floated and didn't.",
    "pda_practical_counterfactual": "I could have pulled out when the warehouse plan was first floated"
  }
]
